SZGame3D.runProject(function __szProjectRun() {
  const __szProjectRunContext = window.__SZProjectLifecycle.begin(() => SZGame3D.restart());
  // Ao iniciar
  const cena = SZGame3D.createFullscreenScene("#94d5f5");
  SZGame3D.frameScene(cena, 24, 7, 14);
  const cenario = SZGame3D.createModelFile(cena, "praia-tropical", 140);
  SZGame3D.setPosition(cenario, 0, 33.6, 0);
  const farol = SZGame3D.createModelFile(cena, "farol-listrado", 5.3);
  SZGame3D.setPosition(farol, 5.2, 2.65, 0.1);
  const barco = SZGame3D.createModelFile(cena, "veleiro", 3.1);
  SZGame3D.setPosition(barco, 13, 1.06, 4.5);
  const pedra = SZGame3D.createModelFile(cena, "pedras", 4.5298);
  SZGame3D.setPosition(pedra, -2.0258, 1.1897, -0.5081);
  const personagem = SZGame3D.createModelFile(cena, "aventureiro", 1.66);
  SZGame3D.setPosition(personagem, -6.5, 0.8, 0.75);
  const chave = SZGame3D.createModelFile(cena, "chave-dourada", 1.24);
  SZGame3D.setPosition(chave, -3, 1, -2);
  const placa = SZGame3D.createModelFile(cena, "placa-da-ordem", 1.5);
  SZGame3D.setPosition(placa, -7.9, 0.73, 3.11);
  const sol = SZGame3D.createModelFile(cena, "pedra-sol", 0.939);
  SZGame3D.setPosition(sol, -6.005, 0.405, 3.04);
  const lua = SZGame3D.createModelFile(cena, "pedra-lua", 0.964);
  SZGame3D.setPosition(lua, -4.172, 0.415, 4.332);
  const estrela = SZGame3D.createModelFile(cena, "pedra-estrela", 0.8767);
  SZGame3D.setPosition(estrela, -2.428, 0.405, 3.081);
  const bau = SZGame3D.createModelFile(cena, "bau-do-tesouro", 1.12);
  SZGame3D.setPosition(bau, -0.6, 0.52, 3);
  let passo = 0;
  SZGame3D.walkArea(personagem, -11, 1, -5, 5);
  SZGame3D.walkArea(personagem, 0.6, 4.1, 0.4, 1.1);
  SZGame3D.walkArea(personagem, 4, 6.1, -0.5, 1.7);
  SZGame3D.setSolid(cenario);
  SZGame3D.setSolid(pedra);
  SZGame3D.walkAnimations(personagem, "parado", "andando");
  let ganhou = false;
  let aviso = "Toque os símbolos na ordem da placa para abrir o baú.";
  let temChave = false;
  SZGame3D.hudText("bottom-center", "Setas ou WASD: andar. R: recomeçar.");
  // Quando acontecer
  SZGame3D.onKey("KeyR", () => {
    SZGame3D.restart();
  });
  SZGame3D.onTouch(personagem, chave, () => {
    SZGame3D.setVisible(chave, "hide");
    temChave = true;
    aviso = "Você pegou a chave! Agora vá ao farol.";
  });
  SZGame3D.onTouch(personagem, farol, () => {
    if (temChave) {
      SZGame3D.playAnimation(farol, "acender", "uma-vez");
      ganhou = true;
      aviso = "Você acendeu o farol! O barco pode chegar.";
    } else {
      aviso = "Falta a chave. Procure na ilha antes de voltar.";
    }
  });
  SZGame3D.onTouch(personagem, sol, () => {
    passo = 1;
    SZGame3D.playAnimation(sol, "acender", "uma-vez");
    aviso = "O sol acendeu! Agora a lua.";
  });
  SZGame3D.onTouch(personagem, lua, () => {
    if (passo === 1) {
      passo = 2;
      SZGame3D.playAnimation(lua, "acender", "uma-vez");
      aviso = "A lua acendeu! Agora a estrela.";
    } else {
      passo = 0;
      SZGame3D.playAnimation(sol, "apagar", "uma-vez");
      SZGame3D.playAnimation(lua, "apagar", "uma-vez");
      aviso = "Fora da ordem. Comece de novo pelo sol.";
    }
  });
  SZGame3D.onTouch(personagem, estrela, () => {
    if (passo === 2) {
      SZGame3D.playAnimation(estrela, "acender", "uma-vez");
      SZGame3D.playAnimation(bau, "abrir", "uma-vez");
      aviso = "Na ordem certa! O baú abriu.";
    } else {
      passo = 0;
      SZGame3D.playAnimation(sol, "apagar", "uma-vez");
      SZGame3D.playAnimation(lua, "apagar", "uma-vez");
      aviso = "Fora da ordem. Comece de novo pelo sol.";
    }
  });
  // Enquanto estiver rodando
  SZGame3D.animate(cena, () => {
    SZGame3D.topDown(personagem, 4);
    SZGame3D.hudText("top-center", aviso);
    if (ganhou) {
      SZGame3D.moveTowards(barco, 6.6, 1.06, 4.5, 1.8);
      if (SZGame3D.animationDone(farol)) {
        SZGame3D.playAnimation(farol, "aceso", "repetir");
      }
    }
  });
});

